sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float radius;
uniform float speed;
uniform float direction;
uniform float mix;
half4 main(float2 coord) {
    half4 base = image.eval(coord);
    if (base.a <= 0.0) return base;
    float angle = radians(direction);
    float2 axis = float2(cos(angle), sin(angle));
    float phase = time * speed;
    float wave = sin(phase + coord.y * 0.025) * 0.35 + cos(phase * 0.7 + coord.x * 0.018) * 0.25;
    float displacement = radius * strength * (0.5 + abs(wave));
    float2 offset = axis * displacement;
    half4 redSample = image.eval(clamp(coord + offset, float2(0.0), size));
    half4 blueSample = image.eval(clamp(coord - offset, float2(0.0), size));
    half4 greenSample = image.eval(clamp(coord + axis * (wave * radius * strength * 0.35), float2(0.0), size));
    half3 warped = half3(redSample.r, greenSample.g, blueSample.b);
    half3 original = base.rgb / max(base.a, 0.0001);
    half3 separated = warped / max(base.a, 0.0001);
    half3 result = mix(original, separated, half(mix));
    return half4(clamp(result, half3(0.0), half3(1.0)) * base.a, base.a);
}
